<?php
namespace App\Http\Controllers\App;
use App\Enums\UserRole; use App\Http\Controllers\Controller; use App\Models\ConsultantProfile; use App\Models\Permission; use Illuminate\Http\Request;
class ConsultantPermissionController extends Controller { public function edit(Request $request,ConsultantProfile $consultant){abort_unless($request->user()->role===UserRole::MANAGER && $request->user()->company_id===$consultant->company_id,403);$permissions=Permission::orderBy('module')->orderBy('name')->get()->groupBy('module');$selected=$consultant->user->permissions()->pluck('permissions.id')->all();return view('app.consultants.permissions',compact('consultant','permissions','selected'));} public function update(Request $request,ConsultantProfile $consultant){abort_unless($request->user()->role===UserRole::MANAGER && $request->user()->company_id===$consultant->company_id,403);$data=$request->validate(['permissions'=>['nullable','array'],'permissions.*'=>['integer','exists:permissions,id']]);$consultant->user->syncPermissions($data['permissions'] ?? []);return redirect()->route('app.consultants.index')->with('success','Consultant permissions updated.');} }
